public class Complex_sqrt_TriageGen1Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testSqrt_PositiveRealWithImaginary() {
        // Test the branch where real >= 0.0
        // sqrt(3 + 4i) = 2 + 1i
        // abs = 5, t = sqrt((3+5)/2) = 2. imag = 4 / (2*2) = 1
        Complex c = new Complex(3.0, 4.0);
        Complex result = c.sqrt();
        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }






}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_sqrt_TriageGen1Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testSqrt_NegativeReal_PositiveImaginary() {
        // Test the branch where real < 0.0 and imaginary > 0
        // sqrt(-3 + 4i) = 1 + 2i
        // abs = 5, t = sqrt((|-3|+5)/2) = 2. 
        // real < 0 branch: real = abs(4)/(2*2) = 1, imag = indicator(4)*2 = 2
        Complex c = new Complex(-3.0, 4.0);
        Complex result = c.sqrt();
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(2.0, result.getImaginary(), EPSILON);
    }




}

